INSERT INTO "Categoria" (id,nombre,activo,"creadoEn","actualizadoEn") SELECT gen_random_uuid()::text,'Otros servicios',true,NOW(),NOW() WHERE NOT EXISTS (SELECT 1 FROM "Categoria" c WHERE lower(c.nombre)=lower('Otros servicios')) AND NOT EXISTS (SELECT 1 FROM "CategoriaNombre" n WHERE lower(n.nombre)=lower('Otros servicios'));
INSERT INTO "CategoriaNombre" (nombre,"categoriaId") SELECT 'Otros servicios',c.id FROM "Categoria" c WHERE lower(c.nombre)=lower('Otros servicios') AND NOT EXISTS (SELECT 1 FROM "CategoriaNombre" n WHERE lower(n.nombre)=lower('Otros servicios')) ON CONFLICT (nombre) DO NOTHING;
